// Turn the Config values into one search job per hashtag and feed type.
// Each search costs about one credit per page, so the total is capped as a safety net.
const cfg = $input.first().json;
const MAX_SEARCHES_PER_RUN = 10;
const MAX_POSTS_PER_SEARCH = 100;

const split = v => String(v ?? '').split(/[,\n]/).map(s => s.trim()).filter(Boolean);
const uniq = a => [...new Set(a)];

const tags = uniq(split(cfg.hashtags).map(t => t.replace(/^#+/, '').replace(/\s+/g, '').toLowerCase()).filter(Boolean));
const feeds = uniq(split(cfg.feedTypes).map(t => t.toLowerCase()).filter(t => t === 'posts' || t === 'reels'));
if (feeds.length === 0) feeds.push('posts');

if (tags.length === 0) {
  throw new Error('No hashtags configured. Add at least one hashtag in the "Config" node.');
}
if (tags.length * feeds.length > MAX_SEARCHES_PER_RUN) {
  throw new Error(`Too many searches (${tags.length * feeds.length}). Limit is ${MAX_SEARCHES_PER_RUN} per run to protect your quota. Remove hashtags or feed types in the "Config" node.`);
}

const limit = Math.min(Math.max(Math.floor(Number(cfg.maxPostsPerSearch) || 50), 1), MAX_POSTS_PER_SEARCH);
const runStartedAt = new Date().toISOString();

const jobs = [];
for (const tag of tags) {
  for (const feedType of feeds) {
    jobs.push({ json: { tag, feedType, limit, runStartedAt } });
  }
}
return jobs;

// Runs once per loop iteration (one hashtag and feed type).
// The search node may return posts, one error item, or one empty item.
// Always return at least one item, otherwise the loop stops early and skips the remaining searches.
const job = $('Batch Process Searches').first().json;
const out = [];
let failure = null;

for (const item of $input.all()) {
  const j = item.json || {};
  if (j.url) {
    // Our fields go last so a new API field can never overwrite them.
    out.push({ json: { ...j, _kind: 'post', tag: job.tag, feedType: job.feedType } });
  } else if (j.error !== undefined && j.error !== null) {
    failure = typeof j.error === 'string' ? j.error : JSON.stringify(j.error);
  }
}

if (failure !== null) {
  out.push({ json: { _kind: 'error', tag: job.tag, feedType: job.feedType, message: failure.slice(0, 300) } });
}
if (out.length === 0) {
  out.push({ json: { _kind: 'empty', tag: job.tag, feedType: job.feedType } });
}
return out;

// Filter, rank and cap giveaway candidates, then build the Telegram messages.
// This node only READS state. State is written after Telegram confirms delivery
// ("Mark posts as sent"), so a failed run never loses a post.
const cfg = $('Set Configuration Values').first().json;
const jobs = $('Build Search Jobs').all();
const store = $getWorkflowStaticData('global');
const isManual = $execution.mode === 'manual';
const runStartedAt = jobs[0] ? jobs[0].json.runStartedAt : new Date().toISOString();

const list = v => String(v ?? '').split(/[,\n]/).map(s => s.trim().toLowerCase().replace(/\s+/g, ' ')).filter(Boolean);
const escRe = s => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
// Whole-word match, so "free" does not hit "freedom" or "carefree".
const phraseRe = p => new RegExp('(^|[^\\p{L}\\p{N}])' + escRe(p).replace(/ /g, '\\s+') + '($|[^\\p{L}\\p{N}])', 'u');
const esc = t => String(t ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const include = list(cfg.includePhrases).map(p => ({ p, re: phraseRe(p) }));
const required = list(cfg.requirePhrases).map(p => ({ p, re: phraseRe(p) }));
const excluded = list(cfg.excludePhrases).map(p => ({ p, re: phraseRe(p) }));
const minMatches = Math.max(1, Math.floor(Number(cfg.minIncludeMatches) || 1));
const minLikes = Number(cfg.minLikes) || 0;
const maxMessages = Math.max(1, Math.floor(Number(cfg.maxMessagesPerRun) || 15));
const maxAgeMs = (Number(cfg.maxPostAgeHours) || 48) * 3600000;
const chatId = cfg.telegramChatId;

// Cutoff: since the last fully successful run (minus 30 min buffer for late-indexed posts),
// but never older than the max post age. Seen keys catch anything re-fetched inside the buffer.
const now = Date.now();
const lastRun = Date.parse(store.lastSuccessfulRun || '');
const cutoff = isNaN(lastRun) ? now - maxAgeMs : Math.max(lastRun - 30 * 60000, now - maxAgeMs);
const seen = new Set(Array.isArray(store.seenKeys) ? store.seenKeys : []);

const stats = { scanned: 0, duplicates: 0, alreadySent: 0, tooOld: 0, lowLikes: 0, missingRequired: 0, excluded: 0, noPhraseMatch: 0 };
const errors = [];
const accepted = new Map();
const rejected = new Set();

for (const { json: p } of $input.all()) {
  if (p._kind === 'error') { errors.push(p); continue; }
  if (p._kind !== 'post') continue;
  stats.scanned++;

  // Stable dedupe key: platform + cleaned URL (no query string, no trailing slash).
  const key = `${p.platform || 'instagram'}:${String(p.url).split('?')[0].replace(/\/+$/, '')}`;
  if (accepted.has(key)) {
    const prev = accepted.get(key);
    if (!prev.tags.includes(p.tag)) prev.tags.push(p.tag);
    stats.duplicates++;
    continue;
  }
  if (rejected.has(key)) { stats.duplicates++; continue; }

  const reject = reason => { stats[reason]++; rejected.add(key); };
  const postedMs = Date.parse(p.posted_at || '');
  const caption = String(p.caption ?? '').toLowerCase().replace(/\s+/g, ' ');

  if (seen.has(key)) { reject('alreadySent'); continue; }
  if (!isNaN(postedMs) && postedMs < cutoff) { reject('tooOld'); continue; }
  // likes can be null, so only apply the threshold when a number is present.
  if (typeof p.likes === 'number' && p.likes < minLikes) { reject('lowLikes'); continue; }
  if (required.some(r => !r.re.test(caption))) { reject('missingRequired'); continue; }
  if (excluded.some(r => r.re.test(caption))) { reject('excluded'); continue; }
  const matched = include.filter(r => r.re.test(caption)).map(r => r.p);
  if (include.length > 0 && matched.length < Math.min(minMatches, include.length)) { reject('noPhraseMatch'); continue; }

  accepted.set(key, {
    key, url: p.url, author: p.author || 'unknown', postedMs: isNaN(postedMs) ? null : postedMs,
    likes: typeof p.likes === 'number' ? p.likes : null,
    caption: String(p.caption ?? ''), matched, tags: [p.tag], score: matched.length
  });
}

// Rank: most matched phrases first, then newest. Cap how many messages one run may send.
const ranked = [...accepted.values()].sort((a, b) => b.score - a.score || (b.postedMs || 0) - (a.postedMs || 0));
const toSend = ranked.slice(0, maxMessages);
const overflow = ranked.length - toSend.length;
const clean = errors.length === 0 && overflow === 0;

const ago = ms => {
  if (ms === null) return 'time unknown';
  const min = Math.max(0, Math.round((now - ms) / 60000));
  return min < 60 ? `${min} min ago` : `${Math.round(min / 60)} h ago`;
};

const out = toSend.map((c, i) => {
  const snippet = c.caption.replace(/\s+/g, ' ').trim();
  const lines = [
    '<b>New giveaway candidate</b>',
    `@${esc(c.author)} | ${ago(c.postedMs)}${c.likes === null ? '' : ` | ${c.likes} likes`}`,
    `Found via: ${c.tags.map(t => '#' + esc(t)).join(', ')}`,
    `Matched: ${c.matched.length ? esc(c.matched.join(', ')) : 'no phrase filter set'}`,
    '',
    snippet ? `"${esc(snippet.length > 160 ? snippet.slice(0, 160) + '...' : snippet)}"` : '(no caption)',
    '',
    esc(c.url)
  ];
  if (i === toSend.length - 1 && overflow > 0) lines.push('', `${overflow} more match${overflow === 1 ? '' : 'es'} queued for the next run.`);
  return { kind: 'post', chatId, key: c.key, text: lines.join('\n'), _clean: clean, _runStartedAt: runStartedAt, _stats: stats };
});

// Search failures: one combined alert, at most once per cooldown (always on manual runs).
const ALERT_COOLDOWN_MS = 6 * 3600000;
const cooledDown = !(now - Date.parse(store.lastErrorAlertAt || '') < ALERT_COOLDOWN_MS);
if (errors.length > 0 && (isManual || cooledDown)) {
  const all = errors.map(e => e.message).join(' ');
  let hint = 'The failed searches are retried on the next run.';
  if (/401|unauthori|invalid_api_key|api key/i.test(all)) hint = 'Check the API key in your RecentReborn credential.';
  else if (/403|forbidden|plan_restricted/i.test(all)) hint = 'Your RecentReborn plan needs API access.';
  else if (/429|rate|too many|quota/i.test(all)) hint = 'Daily quota or the 20 requests/minute limit was hit. Increase "secondsBetweenSearches" or wait for the quota reset.';
  else if (/400|invalid_parameter/i.test(all)) hint = 'A search parameter was rejected. Check hashtags and feed types in the Config node.';
  const lines = errors.map(e => `- #${esc(e.tag)} (${esc(e.feedType)}): ${esc(e.message)}`);
  out.push({
    kind: 'status', chatId,
    text: `<b>${errors.length} of ${jobs.length} RecentReborn search${jobs.length === 1 ? '' : 'es'} failed</b>\n\n${lines.join('\n')}\n\n${esc(hint)}`
  });
  store.lastErrorAlertAt = new Date().toISOString();
}

if (toSend.length === 0 && errors.length === 0) {
  // Nothing to deliver and nothing failed: this run is complete, so advance the cursor.
  store.lastSuccessfulRun = runStartedAt;
  store.lastRunAt = new Date().toISOString();
  if (isManual) {
    out.push({
      kind: 'status', chatId,
      text: `<b>Test run complete</b>\nNo new giveaway matches.\n\nSearches: ${jobs.length}\nPosts scanned: ${stats.scanned}\nAlready sent: ${stats.alreadySent}\nToo old: ${stats.tooOld}\nNo phrase match: ${stats.noPhraseMatch}\nExcluded phrase: ${stats.excluded}\nMissing required phrase: ${stats.missingRequired}\nBelow minimum likes: ${stats.lowLikes}\n\nState is only saved on scheduled runs, so a manual test never marks posts as seen.`
    });
  }
}

// An empty array ends the run quietly.
return out.map(json => ({ json }));

// Runs only for messages Telegram accepted. Commits state for exactly those posts.
// Posts that failed to send stay unmarked and are picked up again on the next run.
const store = $getWorkflowStaticData('global');
const posts = $('Filter and Rank Giveaways').all().map(i => i.json).filter(j => j.kind === 'post');
const delivered = $input.all();

// Map each delivered message back to its post: by pairing index, else by URL in the message text.
const sent = new Set();
delivered.forEach((item, i) => {
  const pi = Array.isArray(item.pairedItem) ? item.pairedItem[0] : item.pairedItem;
  let idx = pi && typeof pi.item === 'number' ? pi.item : -1;
  if (idx < 0 || !posts[idx]) {
    const raw = JSON.stringify(item.json || {});
    idx = posts.findIndex(p => raw.includes(String(p.key).replace(/^[a-z]+:/, '')));
  }
  if (idx < 0 && delivered.length === posts.length) idx = i;
  if (idx >= 0 && posts[idx]) sent.add(idx);
});

const seen = Array.isArray(store.seenKeys) ? store.seenKeys : [];
for (const idx of sent) seen.push(posts[idx].key);
store.seenKeys = seen.slice(-2000); // keep the list bounded

// Advance the cursor only when everything was delivered and no search failed or overflowed.
const allSent = sent.size === posts.length;
if (allSent && posts[0] && posts[0]._clean) store.lastSuccessfulRun = posts[0]._runStartedAt;
store.lastRunAt = new Date().toISOString();
store.totalSent = (Number(store.totalSent) || 0) + sent.size;
store.lastRun = { sent: sent.size, expected: posts.length, stats: posts[0] ? posts[0]._stats : null };

return [{ json: { sent: sent.size, expected: posts.length, totalSentAllTime: store.totalSent } }];

// Telegram rejected one or more giveaway messages. Fail the run visibly so it shows up in the
// Executions list (and in any Error Trigger workflow). Unsent posts were not marked as seen,
// so the next run sends them again.
const failed = $input.all();
const reason = (failed[0].json.error && (failed[0].json.error.message || failed[0].json.error)) || 'unknown error';
throw new Error(`Telegram could not deliver ${failed.length} giveaway message(s): ${String(reason).slice(0, 200)}. They will be retried on the next run. Check the Telegram credential and the chat ID in the Config node.`);
